const root=document.querySelector('#game');
const scene=new THREE.Scene();
const camera=new THREE.PerspectiveCamera(76,innerWidth/innerHeight,.1,220); camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;root.appendChild(renderer.domElement);
let mapType='delta',running=false,ended=false,health=100,armor=35,alive=20,kills=0,zoneClock=120,zoneRadius=48,elapsed=0,toastTimer=0,matchTimer=0;
const player={pos:new THREE.Vector3(0,0,0),yaw:0,pitch:0,speed:8.5,weapon:null,ammo:0,mag:0,reload:0,fire:0};
let bots=[],loot=[],decor=[],obstacles=[],keys={},last=performance.now(), pointer=false, touchLook=null;
const weapons=[{name:'PULSO-9',type:'SMG',damage:19,range:46,rate:.14,mag:24,reserve:96,color:0xd9ff49},{name:'VETOR-4',type:'RIFLE',damage:27,range:75,rate:.28,mag:18,reserve:72,color:0x5de2e4},{name:'MARTelo',type:'ESCOPETA',damage:13,range:23,rate:.72,mag:6,reserve:30,color:0xff9b58}];
const mats={};function mat(color,roughness=.9,metalness=0){const k=[color,roughness,metalness].join(':');return mats[k]||(mats[k]=new THREE.MeshStandardMaterial({color,roughness,metalness}));}
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,12,8),cylGeo=new THREE.CylinderGeometry(.5,.5,1,8);
function addMesh(geo,material,x,y,z,sx=1,sy=1,sz=1,shadow=true){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=shadow;m.receiveShadow=true;scene.add(m);return m;}
function rnd(seed){let x=seed;return()=>{x=(x*1664525+1013904223)>>>0;return x/4294967296;}}
function clearScene(){for(const o of [...scene.children])scene.remove(o);bots=[];loot=[];decor=[];obstacles=[];}
function makeMap(type){clearScene();mapType=type;const delta=type==='delta';scene.background=new THREE.Color(delta?0x9abdc0:0xc2aa82);scene.fog=new THREE.Fog(delta?0x9abdc0:0xc2aa82,delta?48:64,delta?145:180);
scene.add(new THREE.HemisphereLight(delta?0xc8eeeb:0xffdfb1,delta?0x354e45:0x634938,2.1));const sun=new THREE.DirectionalLight(delta?0xffe6bc:0xffd49a,3.2);sun.position.set(-24,42,18);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-60;sun.shadow.camera.right=60;sun.shadow.camera.top=60;sun.shadow.camera.bottom=-60;scene.add(sun);
const ground=addMesh(new THREE.PlaneGeometry(120,120),mat(delta?0x556b56:0xb39465),0,-.24,0,1,1,1,false);ground.rotation.x=-Math.PI/2;
const rand=rnd(delta?241:891);if(delta){const water=addMesh(new THREE.PlaneGeometry(180,180),new THREE.MeshStandardMaterial({color:0x447f83,roughness:.36,metalness:.18}),0,-.48,0,1,1,1,false);water.rotation.x=-Math.PI/2;
for(let i=0;i<24;i++){let x=(rand()-.5)*95,z=(rand()-.5)*95;if(Math.hypot(x,z)<13)continue;let w=2+rand()*5,h=.35+rand()*.45;addMesh(boxGeo,mat(i%3?0x68725c:0x827359),x,-.06,z,w,h,2+rand()*5);}
// floating reed islands and distinctive glass monoliths
for(let i=0;i<14;i++){const a=rand()*Math.PI*2,r=14+rand()*29,x=Math.cos(a)*r,z=Math.sin(a)*r;const island=addMesh(new THREE.CylinderGeometry(3+rand()*3,3.5+rand()*3,.8,7),mat(i%2?0x6a7956:0x7d8160),x,-.05,z,1,1,1);island.rotation.y=rand()*3;for(let j=0;j<3;j++){const h=2+rand()*5;const reed=addMesh(cylGeo,mat(i%3===0?0x5e7b70:0x73745a),x+(rand()-.5)*4,h/2-.15,z+(rand()-.5)*4,.16,h,.16);decor.push(reed);}}
for(const [x,z,h] of [[-19,-12,7],[20,12,9],[4,-27,6],[-30,20,5],[28,-23,8]]){const crystal=addMesh(new THREE.OctahedronGeometry(1),new THREE.MeshStandardMaterial({color:0x7de3d5,roughness:.18,metalness:.3,emissive:0x123f36}),x,h/2,z,1.2,h,1.2);crystal.rotation.y=rand()*3;}
}else{for(let i=0;i<23;i++){const x=(rand()-.5)*92,z=(rand()-.5)*92;if(Math.hypot(x,z)<13)continue;const h=2+rand()*10,w=3+rand()*8;const rock=addMesh(boxGeo,mat(i%3?0x806c51:0xa68b63),x,h/2-.2,z,w,h,4+rand()*8);rock.rotation.y=rand()*Math.PI;}
for(let i=0;i<8;i++){const x=(rand()-.5)*70,z=(rand()-.5)*70;if(Math.hypot(x,z)<15)continue;const pole=addMesh(cylGeo,mat(0x42494b,.55,.3),x,5,z,.2,10,.2);const dish=addMesh(sphereGeo,mat(0xb4a68a,.5,.5),x,10.3,z,.9,.18,.9);dish.rotation.x=.4;decor.push(pole,dish);}}
// original landmarks, scattered cover and lootable supply cases
const huts=delta?[[-17,4],[13,-7],[3,22],[-31,-12],[28,20]]:[[-16,4],[14,-8],[4,24],[-32,-11],[29,19]];
for(let i=0;i<huts.length;i++){const [x,z]=huts[i];const building=addMesh(boxGeo,mat(delta?(i%2?0x806c53:0x596a62):(i%2?0x8c7151:0x746047)),x,1.4,z,6,2.8,5);building.rotation.y=(i%3)*.35;obstacles.push({x,z,r:4.1});const roof=addMesh(boxGeo,mat(delta?0x36494b:0x50443a),x,3,z,6.6,.4,5.6);roof.rotation.y=building.rotation.y;
const crate=addMesh(boxGeo,mat(0x9a7744),x+(i%2?5:-5),.55,z+4,1.2,1.1,1);crate.userData.crate=true;}
// unique signal tower landmark
const tower=addMesh(cylGeo,mat(delta?0x4a6967:0x56493a),0,4,0,.7,8,.7);for(let y=5;y<9;y+=1.6){const ring=addMesh(new THREE.TorusGeometry(1.3,.09,6,16),mat(0xd8ff3e,.4,.4),0,y,0);ring.rotation.x=Math.PI/2;}
// 20 contestants in distinct original silhouettes
for(let i=0;i<19;i++){let a=rand()*Math.PI*2,r=22+rand()*21,x=Math.cos(a)*r,z=Math.sin(a)*r;const color=[0xe47a51,0x6f9c8b,0xb184d1,0xc0a954,0x5489aa,0xc87882][i%6];const group=new THREE.Group();group.position.set(x,0,z);scene.add(group);const torso=addMesh(boxGeo,mat(color),0,1.12,0,.68,1.12,.4);const head=addMesh(sphereGeo,mat(0xd8af88),0,1.91,0,.3,.34,.3);const pack=addMesh(boxGeo,mat(0x34434a),0,1.25,-.28,.45,.6,.2);const leg1=addMesh(boxGeo,mat(0x303a3d),-.19,.39,0,.22,.78,.26),leg2=addMesh(boxGeo,mat(0x303a3d),.19,.39,0,.22,.78,.26);group.add(torso,head,pack,leg1,leg2);bots.push({group,health:100,alive:true,speed:2.1+rand()*1.25,think:rand()*1.2,shoot:rand()*1.6,target:null,color,weapon:weapons[i%weapons.length],phase:rand()*6.28,turn:0});}
player.pos.set(0,0,0);camera.position.set(0,1.65,0);camera.rotation.set(0,0,0);player.yaw=0;player.pitch=0;
// glowing weapon pickups and armor cells in the open ground
for(let i=0;i<15;i++){let a=rand()*Math.PI*2,r=6+rand()*34,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<5)continue;let w=weapons[i%3];const base=new THREE.Mesh(boxGeo,mat(w.color,.5,.4));base.position.set(x,.36,z);base.scale.set(.85,.16,.22);base.rotation.y=rand()*Math.PI;scene.add(base);const barrel=addMesh(boxGeo,mat(0x252c2d,.35,.55),x,.42,z,.48,.12,.1);barrel.rotation.y=base.rotation.y;loot.push({x,z,weapon:w,mesh:base,ammo:w.mag*3});}
for(let i=0;i<9;i++){let a=rand()*Math.PI*2,r=8+rand()*34,x=Math.cos(a)*r,z=Math.sin(a)*r;const cell=addMesh(new THREE.OctahedronGeometry(.42),new THREE.MeshStandardMaterial({color:0x65e3e9,emissive:0x12616c,emissiveIntensity:1}),x,.55,z);loot.push({x,z,armor:true,mesh:cell});}
// first-person improvised carbine, attached to view
const gun=new THREE.Group();const gunBody=addMesh(boxGeo,mat(0x252e30,.34,.5),.38,-.31,-.8,.22,.19,.68);const gunBarrel=addMesh(boxGeo,mat(0x11191c,.3,.7),.38,-.27,-1.23,.09,.08,.42);const sight=addMesh(boxGeo,mat(0x748c69,.45,.3),.38,-.18,-.9,.05,.06,.12);gun.add(gunBody,gunBarrel,sight);camera.add(gun);scene.add(camera);}

