function flash(text,duration=1800){const el=document.querySelector('#toast');el.textContent=text;el.style.opacity=1;toastTimer=duration;}
function updateHud(){document.querySelector('#alive').textContent=alive;document.querySelector('#health-text').textContent=Math.ceil(health);document.querySelector('#health-bar').style.width=Math.max(0,health)+'%';document.querySelector('#armor-text').textContent=Math.ceil(armor);document.querySelector('#armor-bar').style.width=Math.max(0,armor)+'%';document.querySelector('#weapon-name').textContent=player.weapon?player.weapon.name:'MÃOS LIVRES';document.querySelector('#ammo').innerHTML=player.weapon?`${player.mag} <small>/ ${player.ammo}</small>`:'— <small>/ —</small>';}
function startMatch(){document.querySelector('#lobby').classList.add('hidden');document.querySelector('#hud').classList.add('active');document.querySelector('#result').classList.remove('show');running=true;ended=false;health=100;armor=35;alive=20;kills=0;zoneClock=120;zoneRadius=48;player.weapon=null;player.ammo=0;player.mag=0;player.reload=0;player.fire=0;makeMap(mapType);updateHud();flash('BUSQUE ARMAS. A ZONA FECHA EM 2 MIN.',3000);if(innerWidth>700)renderer.domElement.requestPointerLock?.();}
function finish(win){if(ended)return;ended=true;running=false;document.exitPointerLock?.();document.querySelector('#result-title').textContent=win?'VITÓRIA':'ELIMINADO';document.querySelector('#result-copy').textContent=win?`ÚLTIMO OPERADOR · ${kills} ELIMINAÇÕES`:`${alive} OPERADORES RESTANTES · ${kills} ELIMINAÇÕES`;document.querySelector('#result').classList.add('show');}
function reload(){if(!player.weapon||player.reload>0||player.mag===player.weapon.mag||player.ammo<=0)return;player.reload=1.15;flash('RECARREGANDO…',900);}
