let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);const speed=keys.ShiftLeft?12:player.speed;if(forward||side){const length=Math.hypot(forward,side)||1;forward/=length;side/=length;const dx=(Math.sin(player.yaw)*forward+Math.cos(player.yaw)*side)*speed*dt,dz=(-Math.cos(player.yaw)*forward+Math.sin(player.yaw)*side)*speed*dt;const nx=THREE.MathUtils.clamp(player.pos.x+dx,-53,53),nz=THREE.MathUtils.clamp(player.pos.z+dz,-53,53);if(!obstacles.some(o=>Math.hypot(nx-o.x,nz-o.z)<o.r)){player.pos.x=nx;player.pos.z=nz;}}
