if(b.target){const tx=b.target.x-p.x,tz=b.target.z-p.z,d=Math.hypot(tx,tz);if(d>4){p.x+=tx/d*b.speed*dt;p.z+=tz/d*b.speed*dt;}b.group.rotation.y=Math.atan2(tx,tz);}
