const hint=document.querySelector('#hint'),near=loot.some(i=>Math.hypot(i.x-player.pos.x,i.z-player.pos.z)<2.7);hint.textContent=near?'[ E ]  PEGAR EQUIPAMENTO':'WASD mover · Shift correr · E pegar · R recarregar';hint.classList.toggle('show',near||innerWidth>700);if(toastTimer>0){toastTimer-=dt*1000;if(toastTimer<=0)document.querySelector('#toast').style.opacity=0;}}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.045,(now-last)/1000);last=now;update(dt);renderer.render(scene,camera);}requestAnimationFrame(animate);

