function animate(now){requestAnimationFrame(animate);const dt=Math.min(.045,(now-last)/1000);last=now;update(dt);renderer.render(scene,camera);}requestAnimationFrame(animate);

function renderShop(){document.querySelector('#wallet').textContent=wallet;document.querySelector('#shop-wallet').textContent=wallet+' ✦';document.querySelector('#skin-grid').innerHTML=skins.map(s=>{const has=owned.includes(s.id),active=equipped===s.id;return `<div class="skin-card ${active?'equipped':''}"><div class="skin-art" style="--skin:${s.color}"></div><div class="skin-name">${s.name}</div><div class="skin-cost">${s.cost?s.cost+' TOKENS':'GRÁTIS'}</div><button class="skin-action" data-skin="${s.id}">${active?'EQUIPADA':has?'EQUIPAR':`COMPRAR · ${s.cost} ✦`}</button></div>`;}).join('');}
function applySleeve(skin){camera.traverse(o=>{if(o.name==='player-sleeve')o.material.color.set(skin.color);});}
function showLobby(){document.exitPointerLock?.();running=false;document.querySelector('#hud').classList.remove('active');document.querySelector('#result').classList.remove('show');document.querySelector('#shop').classList.remove('show');document.querySelector('#lobby').classList.remove('hidden');makeMap(mapType);camera.position.set(42,27,42);camera.lookAt(0,0,0);}
document.querySelectorAll('.map-card').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.map-card').forEach(x=>x.classList.remove('selected'));button.classList.add('selected');mapType=button.dataset.map;makeMap(mapType);camera.position.set(42,27,42);camera.lookAt(0,0,0);}));
document.querySelector('#play').addEventListener('click',startMatch);document.querySelector('#exit').addEventListener('click',showLobby);document.querySelector('#again').addEventListener('click',showLobby);
document.querySelector('#open-shop').addEventListener('click',()=>{renderShop();document.querySelector('#shop').classList.add('show');});document.querySelector('#close-shop').addEventListener('click',()=>document.querySelector('#shop').classList.remove('show'));
document.querySelector('#skin-grid').addEventListener('click',event=>{const button=event.target.closest('[data-skin]');if(!button)return;const skin=skins.find(s=>s.id===button.dataset.skin);if(!skin)return;if(!owned.includes(skin.id)){if(wallet<skin.cost){flash('TOKENS INSUFICIENTES — JOGUE MAIS PARTIDAS',1700);return;}wallet-=skin.cost;owned.push(skin.id);localStorage.setItem('ll-tokens',wallet);localStorage.setItem('ll-owned',JSON.stringify(owned));}equipped=skin.id;localStorage.setItem('ll-equipped',equipped);applySleeve(skin);renderShop();});
document.querySelector('#mobile-fire').addEventListener('pointerdown',e=>{e.preventDefault();shoot();});document.querySelector('#mobile-reload').addEventListener('pointerdown',e=>{e.preventDefault();reload();});document.querySelector('#mobile-pick').addEventListener('pointerdown',e=>{e.preventDefault();pickup();});
document.querySelectorAll('[data-move]').forEach(button=>{const code=button.dataset.move;button.addEventListener('pointerdown',e=>{e.preventDefault();keys[code]=true;button.setPointerCapture(e.pointerId);});for(const name of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(name,()=>keys[code]=false);});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE')pickup();if(e.code==='KeyR')reload();});window.addEventListener('keyup',e=>keys[e.code]=false);
