window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
makeMap('delta');camera.position.set(42,27,42);camera.lookAt(0,0,0);camera.traverse(o=>{if(o.name==='player-sleeve')o.material.color.set((skins.find(s=>s.id===equipped)||skins[0]).color);});renderShop();
